class Solution {
public:
    int minimumSeconds(vector<int>& nums) {
        unordered_map<int, vector<int>> pos;
        int n = nums.size();
        for (int i = 0; i < n; ++i) pos[nums[i]].push_back(i);
        int ans = n;
        for (auto& [val, idxs] : pos) {
            int max_gap = 0;
            int m = idxs.size();
            for (int i = 0; i < m; ++i) {
                int gap = (idxs[(i + 1) % m] - idxs[i] - 1 + n) % n;
                max_gap = max(max_gap, gap);
            }
            ans = min(ans, (max_gap + 1) / 2);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minimumSeconds(List<Integer> nums) {
        Map<Integer, List<Integer>> pos = new HashMap<>();
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            pos.computeIfAbsent(nums.get(i), k -> new ArrayList<>()).add(i);
        }
        int ans = n;
        for (List<Integer> idxs : pos.values()) {
            int maxGap = 0;
            int m = idxs.size();
            for (int i = 0; i < m; i++) {
                int gap = (idxs.get((i + 1) % m) - idxs.get(i) - 1 + n) % n;
                maxGap = Math.max(maxGap, gap);
            }
            ans = Math.min(ans, (maxGap + 1) / 2);
        }
        return ans;
    }
}

