var minimumSeconds = function(nums) {
    const pos = new Map();
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        if (!pos.has(nums[i])) pos.set(nums[i], []);
        pos.get(nums[i]).push(i);
    }
    let ans = n;
    for (const idxs of pos.values()) {
        let maxGap = 0;
        const m = idxs.length;
        for (let i = 0; i < m; i++) {
            const gap = (idxs[(i + 1) % m] - idxs[i] - 1 + n) % n;
            if (gap > maxGap) maxGap = gap;
        }
        ans = Math.min(ans, Math.floor((maxGap + 1) / 2));
    }
    return ans;
};
